-- Module 7: leads get a follow-up day instead of a time, the rules every lead
-- must keep (lost needs a reason; new, contacted and quoted need an owner and a
-- follow-up day; a quote needs a currency), and lead_status_changes, the log the
-- lead timeline reads. Indexes for My follow-ups, the company profile and the
-- lead and company timelines. Triggers are in 0014.
CREATE TABLE "lead_status_changes" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "lead_status_changes_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"lead_id" bigint NOT NULL,
	"from_status" text,
	"to_status" text NOT NULL,
	"lost_reason" text,
	"stay_id" bigint,
	"automatic" boolean DEFAULT false NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"created_by" bigint,
	CONSTRAINT "lead_status_changes_from_check" CHECK ("lead_status_changes"."from_status" IN ('new', 'contacted', 'quoted', 'booked', 'lost')),
	CONSTRAINT "lead_status_changes_to_check" CHECK ("lead_status_changes"."to_status" IN ('new', 'contacted', 'quoted', 'booked', 'lost')),
	CONSTRAINT "lead_status_changes_lost_reason_check" CHECK ("lead_status_changes"."lost_reason" IN ('price', 'dates_unavailable', 'went_elsewhere', 'no_response', 'plans_changed', 'other'))
);
--> statement-breakpoint
DROP INDEX "leads_status_idx";--> statement-breakpoint
-- the follow-up is a day in Colombo, not a moment
ALTER TABLE "leads" RENAME COLUMN "follow_up_at" TO "follow_up_on";--> statement-breakpoint
ALTER TABLE "leads" ALTER COLUMN "follow_up_on" TYPE date USING ("follow_up_on" AT TIME ZONE 'Asia/Colombo')::date;--> statement-breakpoint
ALTER TABLE "lead_status_changes" ADD CONSTRAINT "lead_status_changes_lead_id_leads_id_fk" FOREIGN KEY ("lead_id") REFERENCES "public"."leads"("id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "lead_status_changes" ADD CONSTRAINT "lead_status_changes_stay_id_stays_id_fk" FOREIGN KEY ("stay_id") REFERENCES "public"."stays"("id") ON DELETE set null ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "lead_status_changes" ADD CONSTRAINT "lead_status_changes_created_by_staff_users_id_fk" FOREIGN KEY ("created_by") REFERENCES "public"."staff_users"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "lead_status_changes_lead_idx" ON "lead_status_changes" USING btree ("lead_id","created_at" DESC NULLS LAST);--> statement-breakpoint
CREATE INDEX "stays_company_idx" ON "stays" USING btree ("booking_company_id","arrival_date") WHERE "stays"."deleted_at" IS NULL;--> statement-breakpoint
CREATE INDEX "interactions_company_idx" ON "interactions" USING btree ("company_id","occurred_at" DESC NULLS LAST);--> statement-breakpoint
CREATE INDEX "interactions_lead_idx" ON "interactions" USING btree ("lead_id");--> statement-breakpoint
CREATE INDEX "leads_owner_idx" ON "leads" USING btree ("owner_id","follow_up_on") WHERE "leads"."deleted_at" IS NULL;--> statement-breakpoint
CREATE INDEX "leads_contact_idx" ON "leads" USING btree ("contact_id");--> statement-breakpoint
CREATE INDEX "leads_stay_idx" ON "leads" USING btree ("stay_id");--> statement-breakpoint
CREATE INDEX "leads_status_idx" ON "leads" USING btree ("status","follow_up_on") WHERE "leads"."deleted_at" IS NULL;--> statement-breakpoint
ALTER TABLE "leads" ADD CONSTRAINT "leads_lost_needs_reason_check" CHECK ("leads"."status" <> 'lost' OR "leads"."lost_reason" IS NOT NULL);--> statement-breakpoint
ALTER TABLE "leads" ADD CONSTRAINT "leads_open_needs_owner_check" CHECK ("leads"."status" NOT IN ('new', 'contacted', 'quoted') OR ("leads"."owner_id" IS NOT NULL AND "leads"."follow_up_on" IS NOT NULL));--> statement-breakpoint
ALTER TABLE "leads" ADD CONSTRAINT "leads_quote_currency_check" CHECK ("leads"."quoted_value" IS NULL OR "leads"."currency" IS NOT NULL);--> statement-breakpoint
ALTER TABLE "leads" ADD CONSTRAINT "leads_dates_check" CHECK ("leads"."check_out" IS NULL OR "leads"."check_in" IS NULL OR "leads"."check_out" >= "leads"."check_in");